/*
 * Lazy-loads LikeC4 web component bundles for docs/examples/likec4/likec4.md.
 *
 * A placeholder looks like:
 *   <div class="likec4-embed" data-bundle="..." data-prefix="likec4-minimal"
 *        data-view="index"></div>
 * The bundle (generated by `likec4 codegen webcomponent`) is fetched the first
 * time a placeholder scrolls into view and is shared between placeholders.
 */
(function () {
  var bundles = {};

  function loadBundle(src) {
    if (!bundles[src]) {
      bundles[src] = new Promise(function (resolve, reject) {
        var script = document.createElement("script");
        script.src = src;
        script.onload = resolve;
        script.onerror = reject;
        document.head.appendChild(script);
      });
    }
    return bundles[src];
  }

  function mount(host) {
    if (host.dataset.mounted) return;
    host.dataset.mounted = "true";
    host.textContent = "Loading interactive viewer…";
    loadBundle(host.dataset.bundle)
      .then(function () {
        var view = document.createElement(host.dataset.prefix + "-view");
        view.setAttribute("view-id", host.dataset.view);
        view.setAttribute("browser", "true");
        host.textContent = "";
        host.appendChild(view);
      })
      .catch(function () {
        host.textContent = "Failed to load the interactive viewer.";
      });
  }

  function init() {
    var hosts = document.querySelectorAll(".likec4-embed:not([data-mounted])");
    if (!("IntersectionObserver" in window)) {
      hosts.forEach(mount);
      return;
    }
    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          observer.unobserve(entry.target);
          mount(entry.target);
        }
      });
    });
    hosts.forEach(function (host) {
      observer.observe(host);
    });
  }

  if (typeof document$ !== "undefined") {
    document$.subscribe(init); // instant navigation
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
